using System;using System.Collections.Generic;using System.Diagnostics;using System.Drawing;using System.IO;using System.Linq;using System.Runtime.InteropServices;using System.Threading.Tasks;using System.Windows.Forms;
internal sealed class StagePerformanceSource:Form {
 int prints,placements;
 internal StagePerformanceSource(string name){Text="PrismGlass stage performance "+name;Bounds=new Rectangle(550+name[0]%3*30,180+name[0]%3*30,800,560);StartPosition=FormStartPosition.Manual;BackColor=Color.FromArgb(38,74,118);}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);if(ClientSize.Width<1||ClientSize.Height<1)return;using(var brush=new System.Drawing.Drawing2D.LinearGradientBrush(ClientRectangle,Color.Teal,Color.CornflowerBlue,30))e.Graphics.FillRectangle(brush,20,50,Math.Max(1,ClientSize.Width-40),Math.Max(1,ClientSize.Height-80));e.Graphics.DrawString(Text,SystemFonts.CaptionFont,Brushes.White,24,20);}
 protected override void WndProc(ref Message m){if(m.Msg==0x317)prints++;if(m.Msg==0x46)placements++;if(m.Msg==0x8010){m.Result=new IntPtr(prints);return;}if(m.Msg==0x8011){m.Result=new IntPtr(placements);return;}base.WndProc(ref m);}
}
internal static class TestStagePerformance {
 [DllImport("user32.dll")]static extern bool SetProcessDpiAwarenessContext(IntPtr context);
 [DllImport("user32.dll")]static extern IntPtr SendMessage(IntPtr window,uint message,IntPtr w,IntPtr l);
 [DllImport("user32.dll")]static extern bool SetPhysicalCursorPos(int x,int y);
 [DllImport("user32.dll")]static extern bool GetPhysicalCursorPos(out Point point);
 [DllImport("user32.dll")]static extern IntPtr WindowFromPhysicalPoint(Point point);
 [DllImport("user32.dll")]static extern void mouse_event(uint flags,uint x,uint y,uint data,UIntPtr extra);
 static string root,output;static Form owner;static int result,checks;static readonly List<Process> sources=new List<Process>();static readonly List<object> measurements=new List<object>();
 static List<object> phases;static Stopwatch phaseClock;static int animationStarts;static bool mergeOnly,closeSurface,surfaceClosed;static StageManager faultStage;
 internal static void Phase(string phase){if(phases!=null){phases.Add(new{phase=phase,ms=phaseClock.Elapsed.TotalMilliseconds});if(phase=="animate-start")animationStarts++;if(phase=="surface-created"&&closeSurface&&faultStage!=null){closeSurface=false;var flights=(System.Collections.IEnumerable)typeof(StageManager).GetField("flights",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(faultStage);foreach(var flight in flights){((NativeWindowMotion.GenieSurface)flight.GetType().GetField("surface").GetValue(flight)).Dispose();surfaceClosed=true;break;}}}}
 static void Check(bool ok,string text){File.AppendAllText(Path.Combine(output,"checks.txt"),(ok?"PASS ":"FAIL ")+text+Environment.NewLine);if(!ok)throw new Exception(text);checks++;}
 static async Task Wait(Func<bool> condition,int maximum=3500){var watch=Stopwatch.StartNew();while(!condition()&&watch.ElapsedMilliseconds<maximum)await Task.Delay(10);if(!condition())throw new TimeoutException("Stage fixture wait timed out");}
 static async Task<DockWindow> Source(string name){var process=Process.Start(new ProcessStartInfo(Application.ExecutablePath,"--source "+name){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden});sources.Add(process);await Wait(()=>{process.Refresh();return process.MainWindowHandle!=IntPtr.Zero;});await Task.Delay(100);return new DockWindow{handle=process.MainWindowHandle.ToInt64(),pid=(uint)process.Id,path=Application.ExecutablePath,title=name};}
 static int Count(IEnumerable<DockWindow> windows,uint message){return windows.Sum(w=>SendMessage(new IntPtr(w.handle),message,IntPtr.Zero,IntPtr.Zero).ToInt32());}
 static async Task Measure(StageManager stage,IList<DockWindow> windows,string name,Action begin){
  Point cursor;GetPhysicalCursorPos(out cursor);var point=owner.PointToScreen(new Point(40,50));try{owner.BringToFront();SetPhysicalCursorPos(point.X,point.Y);await Task.Delay(40);Check(WindowFromPhysicalPoint(point)==owner.Handle,"input targets only the isolated controller");mouse_event(2,0,0,0,UIntPtr.Zero);mouse_event(4,0,0,0,UIntPtr.Zero);await Task.Delay(40);}finally{SetPhysicalCursorPos(cursor.X,cursor.Y);}
  var frames=new List<double>();var watch=Stopwatch.StartNew();phases=new List<object>();phaseClock=watch;animationStarts=0;double first=-1,last=-1;int prints=Count(windows,0x8010),placements=Count(windows,0x8011);var cpu=Process.GetCurrentProcess().TotalProcessorTime;
  EventHandler rendered=(s,e)=>{if(stage.Animating){double now=watch.Elapsed.TotalMilliseconds;if(first<0)first=now;if(last>=0)frames.Add(now-last);last=now;}};
  System.Windows.Media.CompositionTarget.Rendering+=rendered;
  try{begin();try{await Wait(()=>!stage.Busy,6500);}catch{File.AppendAllText(Path.Combine(output,"checks.txt"),"INFO timeout "+name+" busy="+stage.Busy+" animating="+stage.Animating+" error="+stage.Error+" groups="+stage.Groups.Count+" internals="+String.Join(";",typeof(StageManager).GetFields(System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Where(f=>new[]{"epoch","switching","pendingStates","capturing","destination","queued"}.Contains(f.Name)).Select(f=>f.Name+"="+f.GetValue(stage)))+Environment.NewLine);throw;}await Task.Delay(30);}finally{System.Windows.Media.CompositionTarget.Rendering-=rendered;}
  Check(sources.All(p=>!p.HasExited),name+" keeps every fixture source alive");
  var sorted=frames.OrderBy(v=>v).ToArray();measurements.Add(new{name=name,phases=phases.ToArray(),elapsedMs=watch.Elapsed.TotalMilliseconds,firstAnimationMs=first,frames=frames.Count,p50Ms=sorted.Length==0?0:sorted[sorted.Length/2],p95Ms=sorted.Length==0?0:sorted[(int)((sorted.Length-1)*.95)],maxMs=sorted.Length==0?0:sorted.Last(),long16=frames.Count(v=>v>16.7),long33=frames.Count(v=>v>33.3),printRequests=Count(windows,0x8010)-prints,positionRequests=Count(windows,0x8011)-placements,cpuMs=(Process.GetCurrentProcess().TotalProcessorTime-cpu).TotalMilliseconds});File.WriteAllText(Path.Combine(output,"timings.json"),new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(measurements));File.AppendAllText(Path.Combine(output,"checks.txt"),"INFO "+name+" groups="+String.Join(";",stage.Groups.Select(g=>g.Name+"/"+g.id+"/"+g.members.Count))+" skipped="+stage.SkippedWindows+Environment.NewLine);Check(stage.Error.Length==0,name+" settles without recovery failure: "+stage.Error);if(name!="reverse-preparing")Check(first>=0&&frames.Count>0,name+" runs its visual transition");
 }
 static async Task Run(){
  var windows=new List<DockWindow>{await Source("A"),await Source("B"),await Source("C")};var screen=Screen.FromHandle(new IntPtr(windows[0].handle));var monitors=new Dictionary<string,Rectangle>{{screen.DeviceName,Rectangle.Inflate(screen.WorkingArea,-8,-8)}};var originals=windows.Select(StageManager.Read).ToArray();
  using(var stage=new StageManager(root,()=>{},()=>windows))using(var poll=new Timer{Interval=100}){
   stage.Configure(true,false,true,monitors);await Wait(()=>!stage.Busy);Check(stage.Groups.Count==3,"three independent source windows join Stage");poll.Tick+=(s,e)=>stage.Configure(true,false,true,monitors);poll.Start();
   var a=stage.Groups.First(g=>g.members.Any(m=>m.window==windows[0]));var b=stage.Groups.First(g=>g.members.Any(m=>m.window==windows[1]));var c=stage.Groups.First(g=>g.members.Any(m=>m.window==windows[2]));
   await Measure(stage,windows,"switch-a",()=>stage.Switch(a,true));await Measure(stage,windows,"switch-b",()=>stage.Switch(b,true));await Measure(stage,windows,"switch-c",()=>stage.Switch(c,true));
   faultStage=stage;await Measure(stage,windows,"merge-current",()=>stage.Merge(b,c));faultStage=null;if(surfaceClosed)Check(c.members.All(m=>!NativeWindowMotion.IsIconic(new IntPtr(m.window.handle))),"one failed overlay preserves the other animation and restores both native windows");Check(stage.Groups.Count==2&&c.members.Count==2,"merge keeps both real windows in one group: groups="+stage.Groups.Count+" destination="+c.members.Count+" source="+b.members.Count);
   if(!mergeOnly){var member=c.members.First(m=>m.window==windows[1]);await Measure(stage,windows,"split",()=>stage.Split(c,member));Check(stage.Groups.Count==3,"split restores independent groups");
   var split=stage.Groups.First(g=>g.members.Contains(member));bool reversedWhilePreparing=false;
   await Measure(stage,windows,"reverse-preparing",()=>{stage.Switch(a,true);var reversal=new Timer{Interval=10};reversal.Tick+=(s,e)=>{reversal.Stop();reversal.Dispose();reversedWhilePreparing=stage.Busy&&!stage.Animating;stage.Switch(split,true);};reversal.Start();});
   Check(reversedWhilePreparing&&animationStarts==1,"a preparation-time reversal uses one transition instead of playing the discarded target");
   Check(!NativeWindowMotion.IsIconic(new IntPtr(member.window.handle))&&NativeWindowMotion.IsIconic(new IntPtr(windows[0].handle)),"preparation reversal restores only the requested endpoint");
   await Measure(stage,windows,"reverse",()=>{stage.Switch(a,true);var reversal=new Timer{Interval=100};reversal.Tick+=(s,e)=>{reversal.Stop();reversal.Dispose();stage.Switch(c,true);};reversal.Start();});}
   poll.Stop();stage.Configure(false,false,true,monitors);await Wait(()=>!stage.Busy);Check(windows.Select((w,i)=>StageManager.Read(w).show==originals[i].show).All(v=>v),"stopping restores every fixture's original visibility");
  }
  File.WriteAllText(Path.Combine(output,"timings.json"),new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(new{measurements=measurements,note="WPF render callbacks and real fixture WM_PRINT/WM_WINDOWPOSCHANGING counts; not physical display presents."}));File.AppendAllText(Path.Combine(output,"checks.txt"),"Completed "+checks+" Stage performance checks."+Environment.NewLine);
 }
 [STAThread]static int Main(string[] args){SetProcessDpiAwarenessContext(new IntPtr(-4));Application.SetUnhandledExceptionMode(UnhandledExceptionMode.ThrowException);Application.EnableVisualStyles();if(args[0]=="--source"){Application.Run(new StagePerformanceSource(args[1]));return 0;}root=args[0];output=args[1];mergeOnly=args.Contains("--merge-only");closeSurface=args.Contains("--close-surface");File.WriteAllText(Path.Combine(output,"checks.txt"),"");owner=new Form{Text="PrismGlass isolated Stage timing",ShowInTaskbar=false,Bounds=new Rectangle(40,40,400,220),StartPosition=FormStartPosition.Manual};owner.Shown+=async(s,e)=>{try{await Run();}catch(Exception error){File.AppendAllText(Path.Combine(output,"checks.txt"),error+Environment.NewLine);result=1;}finally{foreach(var p in sources){if(!p.HasExited){p.CloseMainWindow();if(!p.WaitForExit(500))p.Kill();}p.Dispose();}owner.Close();}};Application.Run(owner);owner.Dispose();return result;}
}
